// Translations for the instance workspace, content browser, version picker and updater.
// Sections are flattened at export time so components can keep using stable dotted keys.
function flattenSections(sections) {
  return Object.fromEntries(
    Object.entries(sections).flatMap(([section, messages]) =>
      Object.entries(messages).map(([key, value]) => [`${section}.${key}`, value])
    )
  );
}

